<script setup lang="ts">
import { useMessage } from "zenless-ui";
import type {
  AdminCosmetic,
  CosmeticAtomicCondition,
  CosmeticCondition,
  CosmeticGrantRecord,
  CosmeticKind,
  CosmeticRarity,
} from "~/types/entities";
import { resolveErrorMessage } from "~/utils/api-error";

const auth = useAuthStore();
const api = useApi();
const message = useMessage();
const router = useRouter();

// 仅管理员可访问。处理「刷新页面时 user 尚未加载」的竞态：
// token 存在但 user 未就绪时保持 checking，等待 fetchSelfUser 完成。
type AccessState = "checking" | "allowed" | "denied";
const accessState = ref<AccessState>("checking");

watch(
  () => [auth.isLogin, auth.user],
  () => {
    if (!auth.isLogin) {
      accessState.value = "denied";
      return;
    }
    if (auth.user) {
      accessState.value = auth.user.isAdmin ? "allowed" : "denied";
    }
  },
  { immediate: true },
);

const activeTab = ref<CosmeticKind>("title");
const cosmetics = ref<AdminCosmetic[]>([]);
const listLoading = ref(false);

const kindLabel = computed(() => (activeTab.value === "title" ? "称号" : "勋章"));
const kindPath = computed(() => (activeTab.value === "title" ? "titles" : "medals"));

const RARITY_OPTIONS: { value: CosmeticRarity; label: string }[] = [
  { value: "common", label: "普通" },
  { value: "rare", label: "稀有" },
  { value: "epic", label: "史诗" },
  { value: "legendary", label: "传说" },
  { value: "special", label: "限定" },
];

const CONDITION_TYPES: { value: CosmeticAtomicCondition["type"]; label: string; needsMin: boolean }[] = [
  { value: "manual", label: "仅手动授予", needsMin: false },
  { value: "level", label: "绳网等级 ≥", needsMin: true },
  { value: "exp", label: "累计绳网信用 ≥", needsMin: true },
  { value: "article_count", label: "发布帖子数 ≥", needsMin: true },
  { value: "comment_count", label: "发布评论数 ≥", needsMin: true },
  { value: "like_received", label: "收到的点赞数 ≥", needsMin: true },
  { value: "checkin_consecutive_days", label: "连续签到天数 ≥", needsMin: true },
  { value: "denny_given", label: "累计投出丁尼 ≥", needsMin: true },
  { value: "follower_count", label: "粉丝数 ≥", needsMin: true },
  { value: "exam_passed", label: "通过入站考试", needsMin: false },
];

const typeNeedsMin = (type: string) =>
  type !== "manual" && type !== "exam_passed";

const loadCosmetics = async () => {
  if (accessState.value !== "allowed") return;
  listLoading.value = true;
  try {
    cosmetics.value = await api.listCosmetics(activeTab.value);
  } catch (err) {
    message.error(resolveErrorMessage(err, `获取${kindLabel.value}列表失败`));
  } finally {
    listLoading.value = false;
  }
};

watch(accessState, (state) => {
  if (state === "allowed") void loadCosmetics();
});

watch(activeTab, () => {
  void loadCosmetics();
});

onMounted(() => {
  if (accessState.value === "allowed") {
    void loadCosmetics();
  }
});

const switchTab = (tab: CosmeticKind) => {
  activeTab.value = tab;
};

// ── 新建/编辑弹窗 ──────────────────────────────────────
const showEditor = ref(false);
const editingItem = ref<AdminCosmetic | null>(null);
const savingEditor = ref(false);

const editorForm = reactive({
  name: "",
  description: "",
  rarity: "common" as CosmeticRarity,
  sortOrder: 0,
  enabled: true,
  imageId: null as number | null,
  imageUrl: "" as string,
  // 条件编辑：rows 为 null 表示单条件模式
  conditionMode: "single" as "single" | "all",
  conditionType: "manual" as CosmeticAtomicCondition["type"],
  conditionMin: 1,
  conditionRows: [] as Array<{ type: CosmeticAtomicCondition["type"]; min: number }>,
});

const openCreate = () => {
  editingItem.value = null;
  editorForm.name = "";
  editorForm.description = "";
  editorForm.rarity = "common";
  editorForm.sortOrder = cosmetics.value.length + 1;
  editorForm.enabled = true;
  editorForm.imageId = null;
  editorForm.imageUrl = "";
  editorForm.conditionMode = "single";
  editorForm.conditionType = "manual";
  editorForm.conditionMin = 1;
  editorForm.conditionRows = [{ type: "level", min: 1 }];
  showEditor.value = true;
};

const openEdit = (item: AdminCosmetic) => {
  editingItem.value = item;
  editorForm.name = item.name;
  editorForm.description = item.description || "";
  editorForm.rarity = item.rarity;
  editorForm.sortOrder = item.sortOrder;
  editorForm.enabled = item.enabled;
  editorForm.imageId = null;
  editorForm.imageUrl = item.image?.url || "";
  const condition = item.condition;
  if (condition && "all" in condition && Array.isArray(condition.all)) {
    editorForm.conditionMode = "all";
    editorForm.conditionRows = condition.all.map((c) => ({
      type: c.type,
      min: "min" in c ? c.min : 1,
    }));
    editorForm.conditionType = "manual";
    editorForm.conditionMin = 1;
  } else if (condition && "type" in condition) {
    editorForm.conditionMode = "single";
    editorForm.conditionType = condition.type;
    editorForm.conditionMin = "min" in condition ? condition.min : 1;
    editorForm.conditionRows = [];
  } else {
    editorForm.conditionMode = "single";
    editorForm.conditionType = "manual";
    editorForm.conditionMin = 1;
    editorForm.conditionRows = [];
  }
  showEditor.value = true;
};

const addConditionRow = () => {
  if (editorForm.conditionRows.length >= 10) {
    message.warning("最多组合 10 个条件");
    return;
  }
  editorForm.conditionRows.push({ type: "level", min: 1 });
};

const removeConditionRow = (index: number) => {
  editorForm.conditionRows.splice(index, 1);
};

const buildCondition = (): CosmeticCondition => {
  if (editorForm.conditionMode === "all") {
    const rows = editorForm.conditionRows
      .filter((row) => row.type !== "manual")
      .map((row) => ({
        type: row.type,
        ...(typeNeedsMin(row.type) ? { min: Math.max(0, Math.floor(row.min)) } : {}),
      })) as CosmeticAtomicCondition[];
    if (rows.length === 0) return { type: "manual" };
    const first = rows[0];
    if (rows.length === 1 && first) return first;
    return { all: rows };
  }
  if (editorForm.conditionType === "manual" || editorForm.conditionType === "exam_passed") {
    return { type: editorForm.conditionType };
  }
  return {
    type: editorForm.conditionType,
    min: Math.max(0, Math.floor(editorForm.conditionMin)),
  } as CosmeticAtomicCondition;
};

const onEditorImageSelected = async (e: Event) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  input.value = "";
  if (!file) return;
  if (!file.type.startsWith("image/")) {
    message.warning("请选择图片文件");
    return;
  }
  try {
    const uploaded = await api.uploadImage(file);
    editorForm.imageId = uploaded.id;
    editorForm.imageUrl = uploaded.url || "";
    message.success("图片已上传");
  } catch (err) {
    message.error(resolveErrorMessage(err, "图片上传失败"));
  }
};

const clearEditorImage = () => {
  editorForm.imageId = null;
  editorForm.imageUrl = "";
};

const submitEditor = async () => {
  if (savingEditor.value) return;
  const name = editorForm.name.trim();
  if (!name) {
    message.warning("请填写名称");
    return;
  }
  if (editorForm.conditionMode === "all" && editorForm.conditionRows.length === 0) {
    message.warning("组合条件至少需要一行");
    return;
  }

  savingEditor.value = true;
  try {
    const payload: {
      name: string;
      description?: string | null;
      rarity?: string;
      enabled?: boolean;
      condition?: unknown;
      sortOrder?: number;
      imageId?: number | null;
    } = {
      name,
      description: editorForm.description.trim() || null,
      rarity: editorForm.rarity,
      enabled: editorForm.enabled,
      condition: buildCondition(),
      sortOrder: editorForm.sortOrder,
    };
    // 编辑时仅在用户更换过图片或明确清除时提交 imageId
    if (editorForm.imageId != null) payload.imageId = editorForm.imageId;
    else if (editingItem.value && !editorForm.imageUrl) payload.imageId = null;

    if (editingItem.value) {
      await api.updateCosmetic(activeTab.value, editingItem.value.documentId, payload);
      message.success("已保存");
    } else {
      await api.createCosmetic(activeTab.value, payload);
      message.success("已创建");
    }
    showEditor.value = false;
    await loadCosmetics();
  } catch (err) {
    message.error(resolveErrorMessage(err, "保存失败"));
  } finally {
    savingEditor.value = false;
  }
};

// ── 授予/撤销弹窗 ─────────────────────────────────────
const showGrant = ref(false);
const grantTarget = ref<AdminCosmetic | null>(null);
const grantUsername = ref("");
const grantReason = ref("");
const granting = ref(false);

const openGrant = (item: AdminCosmetic) => {
  grantTarget.value = item;
  grantUsername.value = "";
  grantReason.value = "";
  showGrant.value = true;
};

const submitGrant = async () => {
  if (granting.value || !grantTarget.value) return;
  const username = grantUsername.value.trim();
  const reason = grantReason.value.trim();
  if (!username) {
    message.warning("请填写用户名");
    return;
  }
  if (!reason) {
    message.warning("请填写授予原因（追溯留痕）");
    return;
  }
  granting.value = true;
  try {
    const result = await api.grantCosmeticToUser(activeTab.value, grantTarget.value.documentId, {
      username,
      reason,
    });
    message.success(result.created ? `已授予给 ${username}` : `${username} 已持有，无需重复授予`);
    showGrant.value = false;
    await loadCosmetics();
    await loadGrants();
  } catch (err) {
    message.error(resolveErrorMessage(err, "授予失败"));
  } finally {
    granting.value = false;
  }
};

// ── 记录内联撤销 ───────────────────────────────────────
const revokingKey = ref<string | null>(null);
const revokeInputKey = ref<string | null>(null);
const revokeReasonInput = ref("");

const startInlineRevoke = (record: CosmeticGrantRecord) => {
  revokeInputKey.value = revokeInputKey.value === record.documentId ? null : record.documentId;
  revokeReasonInput.value = "";
  void record;
};

const confirmInlineRevoke = async (record: CosmeticGrantRecord) => {
  if (revokingKey.value || !record.cosmetic || !record.user) return;
  const reason = revokeReasonInput.value.trim();
  if (!reason) {
    message.warning("请填写撤销原因（追溯留痕）");
    return;
  }
  revokingKey.value = record.documentId;
  try {
    await api.revokeCosmeticFromUser(activeTab.value, record.cosmetic.documentId, {
      username: record.user.username,
      reason,
    });
    message.success(`已撤销 ${record.user.username} 的「${record.cosmetic.name}」`);
    revokeInputKey.value = null;
    revokeReasonInput.value = "";
    await loadGrants();
    await loadCosmetics();
  } catch (err) {
    message.error(resolveErrorMessage(err, "撤销失败"));
  } finally {
    revokingKey.value = null;
  }
};

// ── 启用/停用 & 删除 ──────────────────────────────────
const togglingKey = ref<string | null>(null);

const toggleEnabled = async (item: AdminCosmetic) => {
  if (togglingKey.value) return;
  togglingKey.value = item.documentId;
  try {
    await api.updateCosmetic(activeTab.value, item.documentId, { enabled: !item.enabled });
    item.enabled = !item.enabled;
    message.success(item.enabled ? "已启用" : "已停用（装备中的用户已卸下）");
  } catch (err) {
    message.error(resolveErrorMessage(err, "操作失败"));
  } finally {
    togglingKey.value = null;
  }
};

const deleteItem = async (item: AdminCosmetic) => {
  if (!window.confirm(`确定删除「${item.name}」？此操作不可恢复。`)) return;
  try {
    await api.deleteCosmetic(activeTab.value, item.documentId);
    message.success("已删除");
    await loadCosmetics();
  } catch (err) {
    message.error(resolveErrorMessage(err, "删除失败"));
  }
};

// ── 授予记录（可追溯） ─────────────────────────────────
const showGrants = ref(false);
const grants = ref<CosmeticGrantRecord[]>([]);
const grantsTotal = ref(0);
const grantsLoading = ref(false);
const grantsFilter = reactive({
  includeRevoked: true,
  username: "",
  cosmeticDocumentId: "",
  source: "" as "" | "manual" | "auto",
});

const openGrants = async () => {
  showGrants.value = true;
  await loadGrants();
};

const loadGrants = async () => {
  if (!showGrants.value) return;
  grantsLoading.value = true;
  try {
    const result = await api.listCosmeticGrants(activeTab.value, {
      includeRevoked: grantsFilter.includeRevoked,
      ...(grantsFilter.username.trim() ? { username: grantsFilter.username.trim() } : {}),
      ...(grantsFilter.cosmeticDocumentId ? { cosmeticDocumentId: grantsFilter.cosmeticDocumentId } : {}),
      ...(grantsFilter.source ? { source: grantsFilter.source } : {}),
      limit: 100,
    });
    grants.value = result.records;
    grantsTotal.value = result.total;
  } catch (err) {
    message.error(resolveErrorMessage(err, "获取授予记录失败"));
  } finally {
    grantsLoading.value = false;
  }
};

watch(
  () => [grantsFilter.includeRevoked, grantsFilter.username, grantsFilter.source],
  () => {
    if (showGrants.value) void loadGrants();
  },
);

const grantsCosmeticOptions = computed(() =>
  cosmetics.value.map((item) => ({ value: item.documentId, label: item.name })),
);

// ── 全量重评估 ─────────────────────────────────────────
const evaluating = ref(false);
const runEvaluate = async () => {
  if (evaluating.value) return;
  if (!window.confirm("对全部用户重评估称号/勋章条件？用户量较大时可能需要一些时间。")) return;
  evaluating.value = true;
  try {
    const result = await api.evaluateCosmetics();
    message.success(`评估完成：${result.processed} 位用户，新授予 ${result.granted} 项`);
    await loadCosmetics();
  } catch (err) {
    message.error(resolveErrorMessage(err, "评估失败"));
  } finally {
    evaluating.value = false;
  }
};

/** 从已撤销的记录重新授予（生成新纪录，历史保留） */
const regrantRecord = (record: CosmeticGrantRecord) => {
  if (!record.cosmetic) return;
  const target = cosmetics.value.find((c) => c.documentId === record.cosmetic?.documentId);
  if (!target) {
    message.warning(`「${record.cosmetic.name}」已被删除，无法重新授予`);
    return;
  }
  grantUsername.value = record.user?.username || "";
  grantReason.value = "";
  openGrant(target);
};

const formatTime = (value: string | null) => {
  if (!value) return "-";
  return value.replace("T", " ").slice(0, 16);
};

const goBack = () => {
  router.back();
};

useHead({ title: "管理中心 - 绳网" });
</script>

<template>
  <section class="ik-manage-page">
    <div class="ik-manage-page__stripe" aria-hidden="true"></div>

    <!-- 访问守卫态 -->
    <div v-if="accessState !== 'allowed'" class="ik-manage-inner">
      <div class="ik-manage-access">
        <template v-if="accessState === 'checking'">
          <i class="z-icon-loading ik-spin" /> 正在验证管理员身份...
        </template>
        <template v-else>
          <p>仅管理员可访问此页面。</p>
          <z-button highlight @click="router.push('/')">返回首页</z-button>
        </template>
      </div>
    </div>

    <div v-else class="ik-manage-inner">
      <div class="ik-manage-head">
        <button type="button" class="ik-manage-back" @click="goBack">← 返回</button>
        <h1 class="ik-manage-title">装扮管理中心</h1>
        <span class="ik-manage-sub">称号 / 勋章 · 可控制 · 可追溯 · 可复原</span>
      </div>

      <!-- 资源切换 + 操作 -->
      <div class="ik-manage-toolbar">
        <div class="ik-manage-tabs" role="tablist">
          <button
            type="button"
            role="tab"
            class="ik-manage-tab"
            :class="{ 'is-active': activeTab === 'title' }"
            :aria-selected="activeTab === 'title'"
            @click="switchTab('title')"
          >称号</button>
          <button
            type="button"
            role="tab"
            class="ik-manage-tab"
            :class="{ 'is-active': activeTab === 'medal' }"
            :aria-selected="activeTab === 'medal'"
            @click="switchTab('medal')"
          >勋章</button>
        </div>
        <div class="ik-manage-actions">
          <z-button @click="openGrants">授予记录</z-button>
          <z-button :disabled="evaluating" @click="runEvaluate">
            {{ evaluating ? '评估中...' : '全量重评估' }}
          </z-button>
          <z-button highlight @click="openCreate">新建{{ kindLabel }}</z-button>
        </div>
      </div>

      <!-- 目录表 -->
      <div class="ik-manage-table-wrap">
        <div v-if="listLoading && !cosmetics.length" class="ik-manage-empty">加载中...</div>
        <div v-else-if="!cosmetics.length" class="ik-manage-empty">
          还没有{{ kindLabel }}，点击右上角「新建{{ kindLabel }}」开始
        </div>
        <table v-else class="ik-manage-table">
          <thead>
            <tr>
              <th class="ik-col-name">名称</th>
              <th class="ik-col-rarity">稀有度</th>
              <th class="ik-col-cond">触发条件</th>
              <th class="ik-col-status">状态</th>
              <th class="ik-col-holders">持有人</th>
              <th class="ik-col-ops">操作</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="item in cosmetics" :key="item.documentId">
              <td class="ik-col-name">
                <div class="ik-manage-cos">
                  <img v-if="item.image?.url" :src="item.image.url" :alt="item.name" class="ik-manage-cos__img" />
                  <span v-else class="ik-manage-cos__placeholder">{{ item.name.charAt(0) }}</span>
                  <div class="ik-manage-cos__texts">
                    <strong>{{ item.name }}</strong>
                    <span v-if="item.description">{{ item.description }}</span>
                  </div>
                </div>
              </td>
              <td class="ik-col-rarity">
                <span class="ik-manage-rarity" :class="`is-${item.rarity}`">
                  {{ RARITY_OPTIONS.find((r) => r.value === item.rarity)?.label || item.rarity }}
                </span>
              </td>
              <td class="ik-col-cond">{{ item.conditionDescription }}</td>
              <td class="ik-col-status">
                <span class="ik-manage-status" :class="item.enabled ? 'is-on' : 'is-off'">
                  {{ item.enabled ? '启用' : '停用' }}
                </span>
              </td>
              <td class="ik-col-holders">
                {{ item.activeGrantCount }}
                <span class="ik-manage-holders-total">/ {{ item.totalGrantCount }} 历史授予</span>
              </td>
              <td class="ik-col-ops">
                <button type="button" class="ik-manage-op" @click="openGrant(item)">授予</button>
                <button type="button" class="ik-manage-op" @click="openEdit(item)">编辑</button>
                <button
                  type="button"
                  class="ik-manage-op"
                  :disabled="togglingKey === item.documentId"
                  @click="toggleEnabled(item)"
                >{{ item.enabled ? '停用' : '启用' }}</button>
                <button type="button" class="ik-manage-op ik-manage-op--danger" @click="deleteItem(item)">删除</button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

    <!-- 新建/编辑弹窗 -->
    <ClientOnly>
      <Teleport to="body">
        <Transition name="ik-overlay" appear>
          <div v-if="showEditor" class="ik-manage-overlay" @click.self="showEditor = false">
            <div class="ik-manage-dialog">
              <div class="ik-manage-dialog__header">
                <span>{{ editingItem ? `编辑${kindLabel}` : `新建${kindLabel}` }}</span>
                <button type="button" class="ik-manage-dialog__close" aria-label="关闭" @click="showEditor = false">×</button>
              </div>
              <div class="ik-manage-dialog__body">
                <label class="ik-manage-field">
                  <span class="ik-manage-field__label">名称 *</span>
                  <input v-model="editorForm.name" type="text" maxlength="32" placeholder="不超过 32 字符" />
                </label>
                <label class="ik-manage-field">
                  <span class="ik-manage-field__label">描述</span>
                  <input v-model="editorForm.description" type="text" maxlength="200" placeholder="展示在装扮详情里" />
                </label>
                <div class="ik-manage-field-row">
                  <label class="ik-manage-field">
                    <span class="ik-manage-field__label">稀有度</span>
                    <select v-model="editorForm.rarity">
                      <option v-for="opt in RARITY_OPTIONS" :key="opt.value" :value="opt.value">{{ opt.label }}</option>
                    </select>
                  </label>
                  <label class="ik-manage-field">
                    <span class="ik-manage-field__label">排序（小在前）</span>
                    <input v-model.number="editorForm.sortOrder" type="number" step="1" />
                  </label>
                </div>

                <!-- 触发条件编辑器 -->
                <div class="ik-manage-field">
                  <span class="ik-manage-field__label">触发条件（自定义）</span>
                  <div class="ik-manage-cond-mode">
                    <label class="ik-manage-radio">
                      <input v-model="editorForm.conditionMode" type="radio" value="single" />
                      单条件
                    </label>
                    <label class="ik-manage-radio">
                      <input v-model="editorForm.conditionMode" type="radio" value="all" />
                      组合（全部满足）
                    </label>
                  </div>

                  <div v-if="editorForm.conditionMode === 'single'" class="ik-manage-cond-single">
                    <select v-model="editorForm.conditionType">
                      <option v-for="opt in CONDITION_TYPES" :key="opt.value" :value="opt.value">
                        {{ opt.label }}{{ opt.needsMin ? '' : '' }}
                      </option>
                    </select>
                    <input
                      v-if="typeNeedsMin(editorForm.conditionType)"
                      v-model.number="editorForm.conditionMin"
                      type="number"
                      min="0"
                      step="1"
                    />
                  </div>

                  <div v-else class="ik-manage-cond-rows">
                    <div v-for="(row, idx) in editorForm.conditionRows" :key="idx" class="ik-manage-cond-row">
                      <select v-model="row.type">
                        <option v-for="opt in CONDITION_TYPES" :key="opt.value" :value="opt.value">
                          {{ opt.label }}
                        </option>
                      </select>
                      <input
                        v-if="typeNeedsMin(row.type)"
                        v-model.number="row.min"
                        type="number"
                        min="0"
                        step="1"
                      />
                      <span v-else class="ik-manage-cond-row__spacer"></span>
